// spec: specs/orders.md §22 · кейс .qa/tests/orders/ord-37-edit-server-stock-check.md
// seed: tests/seed.admin.spec.ts
// #929aa5 (עבר QA 26.10): сервер (RPC update_order_items) сам отклоняет кол-во больше доступного остатка — и при обходе UI.
//   Тело RPC: {"p_order_id", "p_items":[{"product_id","qty"[,"unit_price"]}]}. Сверх доступного → 400, code 22023,
//   message «INSUFFICIENT_STOCK:<שם>:<N>»; на экране «הכמות של <שם> גדולה מהמלאי (N). עדכן אותה ונסה שוב.», заказ не меняется.
//   N = физический остаток минус другие ожидающие заказы = число в «במלאי N בלבד» (#6a98bd). Ровно N → 200, сохраняется.
// Обход UI — подмена тела перехваченного запроса «שמור שינויים» (page.route → route.continue({ postData })):
//   заголовки/токены не читаются и не логируются, запрос уходит из самой страницы.
// Данные: товар QA-AUTO-929a-<ts> (₪1, остаток 2 «ללא מקום»); заказ 1 и заказ 2 клиента test — по ×1.
//   Пока заказ 2 ожидает — для заказа 1 доступно 1; после отклонения заказа 2 — 2.
// afterAll: заказы отклоняются, товар удаляется. @data @orders — не параллельно с cart-checkout / order-lifecycle /
//   inventory-lifecycle / picking (общая корзина buyer и остатки).
import { test, expect, Page } from '@playwright/test';
import { auth, createStockedProduct, buyerPlaceOrder, openOrder, rejectIfPending, cleanup } from './_qa-order';

test.use({ storageState: auth('admin') });

const RPC = /\/rest\/v1\/rpc\/update_order_items(\?|$)/;
const stamp = () => `${String(Date.now()).slice(-7)}${Math.floor(Math.random() * 10)}`;
const money = (n: number) => `₪${n.toFixed(2)}`.replace('.', '\\.');
const cardRow = (page: Page, p: string) => page.getByText(p, { exact: true }).first().locator('..');
const rowText = (qty: number, price: number) => new RegExp(`—\\s*${qty}\\s*${money(price)}\\s*${money(qty * price)}`);

async function openEdit(page: Page, no: string) {
  await page.getByRole('button', { name: 'עריכה', exact: true }).click();
  await expect(page.getByRole('heading', { level: 1, name: `עריכת הזמנה #${no}` })).toBeVisible({ timeout: 20_000 });
}

/** «שמור שינויים», а в уходящем update_order_items кол-во товара productId заменяется на forcedQty. Возвращает ответ RPC. */
async function saveWithForcedQty(page: Page, productId: string, forcedQty: number) {
  let sent: { p_order_id?: string; p_items?: { product_id: string; qty: number }[] } = {};
  await page.route(RPC, async (route) => {
    const body = JSON.parse(route.request().postData() || '{}');
    for (const it of body.p_items ?? []) if (it.product_id === productId) it.qty = forcedQty;
    sent = body;
    await route.continue({ postData: JSON.stringify(body) });
  });
  try {
    const resp = page.waitForResponse((r) => RPC.test(r.url()) && r.request().method() === 'POST', { timeout: 20_000 });
    await page.getByRole('button', { name: 'שמור שינויים' }).click();
    const r = await resp;
    return { status: r.status(), body: await r.json().catch(() => ({})), sent };
  } finally {
    await page.unroute(RPC);
  }
}

test.describe('orders — עריכת הזמנה: השרת דוחה כמות גדולה מהמלאי הזמין (#929aa5)', () => {
  test.describe.configure({ mode: 'serial' });
  const ts = stamp();
  const P = `QA-AUTO-929a-${ts}`;
  let productId = '';
  let order1: string | undefined;
  let order2: string | undefined;
  let productCreated = false;

  const qty = (page: Page) => page.getByRole('textbox', { name: `כמות — ${P}`, exact: true });
  const banner = (page: Page, n: number) => page.getByText(`הכמות של ${P} גדולה מהמלאי (${n}). עדכן אותה ונסה שוב.`, { exact: true });

  test.beforeAll(async ({ browser }) => {
    test.setTimeout(300_000);
    const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    try {
      productCreated = true;
      productId = await createStockedProduct(await ctx.newPage(), P, `Q929A-${ts}`, 1, 2);
    } finally { await ctx.close(); }
    order1 = await buyerPlaceOrder(browser, [{ id: productId, name: P, qty: 1 }], `QA-AUTO-929a-${ts}-1`);
    order2 = await buyerPlaceOrder(browser, [{ id: productId, name: P, qty: 1 }], `QA-AUTO-929a-${ts}-2`);
  });
  test.afterAll(async ({ browser }) => {
    test.setTimeout(180_000);
    await cleanup(browser, [order1, order2], productCreated ? [P] : []);
  });

  test.skip('לא דרך הממשק: כמות 2 / 5 כשזמין 1 (הזמנה אחרת ממתינה) — 400 INSUFFICIENT_STOCK:<מוצר>:1, באנר «…גדולה מהמלאי (1)…», ההזמנה לא השתנתה #929aa5 @desktop @orders @data', { annotation: { type: 'skip', description: 'временно отключено 26.10 по просьбе клиента (#e7e338, лимит остатка снят); вернуть вместе с #e02e48 — knowledge/stock-logic-snapshot-2026-10-26.md §5' } }, async ({ page }) => {
    await openOrder(page, order1!);
    await expect(cardRow(page, P)).toHaveText(rowText(1, 1));
    await openEdit(page, order1!);

    // Д1: лимит сервера = число, которое показывает экран
    await qty(page).fill('2');
    await qty(page).press('Tab');
    await expect(page.getByText('במלאי 1 בלבד — לא ניתן להזמין יותר', { exact: true }), 'экран: доступно 1').toBeVisible();
    await qty(page).fill('1');
    await qty(page).press('Tab');
    await expect(page.getByText('במלאי 1 בלבד — לא ניתן להזמין יותר', { exact: true })).toHaveCount(0);

    for (const forced of [2, 5]) {
      const r = await saveWithForcedQty(page, productId, forced);
      expect(r.sent.p_order_id, 'тело RPC содержит p_order_id').toBeTruthy();
      expect(r.sent.p_items?.find((i) => i.product_id === productId)?.qty, `ушло qty=${forced}`).toBe(forced);
      expect(r.status, `qty ${forced}: сервер отклоняет`).toBe(400);
      expect(r.body.code, `qty ${forced}: код ошибки`).toBe('22023');
      expect(r.body.message, `qty ${forced}: текст ошибки`).toBe(`INSUFFICIENT_STOCK:${P}:1`);
      await expect(banner(page, 1), `qty ${forced}: понятное сообщение`).toBeVisible();
      await expect(page.getByRole('heading', { level: 1, name: `עריכת הזמנה #${order1}` }), 'остаёмся в форме').toBeVisible();
    }

    await page.getByRole('button', { name: 'ביטול', exact: true }).click();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${order1}` })).toBeVisible({ timeout: 20_000 });
    await expect(cardRow(page, P), 'в заказе прежнее кол-во 1').toHaveText(rowText(1, 1));
    await page.reload();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${order1}` })).toBeVisible({ timeout: 30_000 });
    await expect(cardRow(page, P), 'и после обновления').toHaveText(rowText(1, 1));
  });

  test.skip('אחרי דחיית ההזמנה האחרת זמין 2: כמות 3 — 400 INSUFFICIENT_STOCK:<מוצר>:2; בדיוק 2 — 200 ונשמר #929aa5 @desktop @orders @data', { annotation: { type: 'skip', description: 'временно отключено 26.10 по просьбе клиента (#e7e338, лимит остатка снят); вернуть вместе с #e02e48 — knowledge/stock-logic-snapshot-2026-10-26.md §5' } }, async ({ page }) => {
    expect(await rejectIfPending(page, order2!, 'QA-AUTO 929a: освободить остаток'), 'заказ 2 отклонён').toBe(true);

    await openOrder(page, order1!);
    await openEdit(page, order1!);
    const r3 = await saveWithForcedQty(page, productId, 3);
    expect(r3.status, 'qty 3 (N+1): сервер отклоняет').toBe(400);
    expect(r3.body.code).toBe('22023');
    expect(r3.body.message, 'N = 2 после освобождения резерва').toBe(`INSUFFICIENT_STOCK:${P}:2`);
    await expect(banner(page, 2)).toBeVisible();

    await qty(page).fill('2');
    await qty(page).press('Tab');
    await expect(page.getByText('במלאי 2 בלבד — לא ניתן להזמין יותר', { exact: true })).toHaveCount(0);
    const ok = page.waitForResponse((r) => RPC.test(r.url()) && r.request().method() === 'POST', { timeout: 20_000 });
    await page.getByRole('button', { name: 'שמור שינויים' }).click();
    expect((await ok).status(), 'ровно доступное: 200').toBe(200);
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${order1}` })).toBeVisible({ timeout: 20_000 });
    await expect(cardRow(page, P)).toHaveText(rowText(2, 1), { timeout: 15_000 });
    await page.reload();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${order1}` })).toBeVisible({ timeout: 30_000 });
    await expect(cardRow(page, P)).toHaveText(rowText(2, 1));
  });
});
